// Aktive Regelgruppen; Zeitraum: die letzten N Tage bis heute
const cfg = $('Einstellungen').first().json;
const iso = (d) => d.toISOString().slice(0, 10);
const end = new Date();
const start = new Date(Date.now() - Number(cfg.tage || 45) * 86400000);
const groups = ($input.first().json.data || []).filter((g) => g.attributes?.active !== false);
if (!groups.length) return [];
return groups.map((g) => ({ json: { id: g.id, titel: g.attributes?.title, url: cfg.firefly_url, start: iso(start), end: iso(end) } }));
